'use server';

import { updateTag } from 'next/cache';
import { redirect } from 'next/navigation';
import { createPostInStore } from '@/lib/posts';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  if (!title?.trim() || !content?.trim()) {
    throw new Error('Title and content are required');
  }

  createPostInStore(title.trim(), content.trim());

  // Invalidate the "posts" cache tag - guarantees next request waits for fresh data,
  // no stale content served (unlike revalidateTag which uses stale-while-revalidate)
  updateTag('posts');

  redirect('/');
}

